// Hand-written on purpose. `app_localizations.dart` is generated by
// `flutter gen-l10n`, and the generator still emits the deprecated
// `flutter_localizations` delegates. Those produce the old Material/Cupertino
// localizations types, which a `material_ui` MaterialApp does not look up, so
// the app composes its own list from material_ui's combined
// Flutter + Material + Cupertino delegates instead.

import 'package:material_ui/material_ui.dart';

import 'app_localizations.dart';

/// Application localizations: our own strings first, then the Material,
/// Cupertino and Widgets defaults provided by `material_ui`.
const List<LocalizationsDelegate<dynamic>> appLocalizationsDelegates =
    <LocalizationsDelegate<dynamic>>[
  AppLocalizations.delegate,
  ...GlobalMaterialLocalizations.delegates,
];
